import {account,mountAccountLink} from './account-client.js';
const main=document.querySelector('#setup-content');
try{await account.requireUser();await mountAccountLink();if(!account.user?.is_admin){main.innerHTML='<h1>启用云端备注</h1><p>请使用管理员账户查看启用说明。</p>';}else{const r=await fetch('assets/setup/005-question-notes.sql',{cache:'no-store'});if(!r.ok)throw Error('启用SQL暂未载入，请刷新重试');const sql=await r.text();main.innerHTML=`<h1>启用云端备注</h1><p class="account-intro">只需项目所有者操作一次。现有账户、收藏、已做记录和管理员权限会保留。</p><ol class="solution-steps"><li>点击“复制全部SQL”。</li><li>打开下面的 Supabase SQL Editor，新建一个查询，粘贴全部内容，点击 <b>Run</b>。</li><li>返回本页，点击“检查启用状态”。看到成功提示后，所有用户即可跨设备保存备注。</li></ol><div class="button-row"><button class="primary" id="copy-notes-sql">复制全部SQL</button><a class="secondary button" href="https://supabase.com/dashboard/project/tftetbicqcnhinnldsln/sql/new" target="_blank" rel="noopener">打开 Supabase SQL Editor ↗</a><button class="secondary" id="check-notes">检查启用状态</button></div><p class="form-message" id="setup-message" role="status"></p><label style="display:block;margin-top:20px">全部SQL（复制失败时可在此全选）<textarea id="setup-sql" readonly rows="18" spellcheck="false" style="width:100%;margin-top:8px;padding:12px;font:12px/1.6 monospace;resize:vertical"></textarea></label><p class="account-small">此SQL建立每人独立的备注表及版本检查接口，并补登记上一版20道提高题。备注正文仅本人可读取，管理员的访问统计不展示其他人的备注。</p>`;document.querySelector('#setup-sql').value=sql;const msg=document.querySelector('#setup-message');document.querySelector('#copy-notes-sql').onclick=async()=>{try{await navigator.clipboard.writeText(sql);msg.textContent='已复制全部SQL。现在打开SQL Editor粘贴运行。';}catch{const t=document.querySelector('#setup-sql');t.focus();t.select();msg.textContent=document.execCommand('copy')?'已复制全部SQL。':'请复制上方已选中的全部SQL。';}};document.querySelector('#check-notes').onclick=async e=>{e.target.disabled=true;try{const rows=await account.rpc('pp_notes_snapshot');if(!Array.isArray(rows))throw Error('服务返回格式不正确');msg.textContent='云端备注已启用。返回题库即可保存；此前本机草稿可重新点击“保存备注”同步。';}catch{msg.textContent='尚未确认启用。请确认SQL已完整运行成功，再点击检查。已有本机草稿会保留。';}finally{e.target.disabled=false;}};}}
catch(e){main.textContent=e.message;}
